# owner: platform
"""Snap clock times to a fixed step, for payroll labels.

A label reads like 09:00-17:15 (8h 15m).
The step must divide 60 evenly or ValueError is raised.
"""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

MINUTES_PER_HOUR = 60


# ---
def round_span_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Snap spans to the step and label them, halves up."""
    _check_step(step)
    return [_label(_snap(span, step)) for span in spans]


def _check_step(step: int) -> None:
    if step <= 0 or MINUTES_PER_HOUR % step:
        raise ValueError(f"step must divide 60: {step}")


def _snap(span: Span, step: int) -> Span:
    start = _round_to_step(span.start, step)
    end = _round_to_step(span.end, step)
    return Span(start, end)


def _round_to_step(minutes: int, step: int) -> int:
    return (minutes + step // 2) // step * step


def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, MINUTES_PER_HOUR)
    return f"{format_span(span)} ({hours}h {minutes}m)"

