# owner: platform
import unittest

from hourglass.rounding import round_span_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_nearest_quarter_hour(self):
        labels = round_span_labels([Span(542, 1036)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = round_span_labels([Span(545, 600)], 10)
        self.assertEqual(labels, ["09:10-10:00 (0h 50m)"])

    def test_below_halfway_rounds_down(self):
        labels = round_span_labels([Span(547, 1048)], 15)
        self.assertEqual(labels, ["09:00-17:30 (8h 30m)"])

    def test_step_of_one_changes_nothing(self):
        labels = round_span_labels([Span(541, 600)], 1)
        self.assertEqual(labels, ["09:01-10:00 (0h 59m)"])

    def test_step_of_an_hour(self):
        labels = round_span_labels([Span(550, 1000)], 60)
        self.assertEqual(labels, ["09:00-17:00 (8h 0m)"])

    def test_end_of_day_is_allowed(self):
        labels = round_span_labels([Span(1430, 1440)], 15)
        self.assertEqual(labels, ["23:45-24:00 (0h 15m)"])

    def test_keeps_order_and_labels_each_span(self):
        spans = [Span(540, 720), Span(780, 1020)]
        labels = round_span_labels(spans, 30)
        self.assertEqual(labels[0], "09:00-12:00 (3h 0m)")
        self.assertEqual(labels[1], "13:00-17:00 (4h 0m)")

    def test_empty_list(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_span_that_rounds_to_nothing(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(541, 544)], 15)

    def test_steps_that_do_not_divide_an_hour(self):
        spans = [Span(540, 600)]
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span_labels(spans, step)
